-- Separate V2 tables. No ABI2 room, projection, keeper or sponsor row is migrated.
CREATE TABLE IF NOT EXISTS v2_match_projections(network_key text NOT NULL,address text NOT NULL,program_id text NOT NULL,slot bigint NOT NULL CHECK(slot>=0),revision bigint NOT NULL CHECK(revision>=0),phase smallint NOT NULL CHECK(phase BETWEEN 0 AND 6),stage smallint NOT NULL CHECK(stage BETWEEN 0 AND 5),seat_count smallint NOT NULL CHECK(seat_count BETWEEN 1 AND 6),projection jsonb NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(network_key,address));
CREATE TABLE IF NOT EXISTS v2_stage_receipts(network_key text NOT NULL,match_address text NOT NULL,stage smallint NOT NULL CHECK(stage BETWEEN 0 AND 5),slot bigint NOT NULL,revision bigint NOT NULL,receipt jsonb NOT NULL,PRIMARY KEY(network_key,match_address,stage));
CREATE TABLE IF NOT EXISTS v2_work_receipts(network_key text NOT NULL,match_address text NOT NULL,stage smallint NOT NULL,job_index smallint NOT NULL,provider smallint NOT NULL,owner_address text NOT NULL,slot bigint NOT NULL,executed boolean NOT NULL,receipt jsonb NOT NULL,PRIMARY KEY(network_key,match_address,stage,job_index));
CREATE TABLE IF NOT EXISTS v2_mission_projections(network_key text NOT NULL,match_address text NOT NULL,vault_program text NOT NULL,slot bigint NOT NULL,projection jsonb NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(network_key,match_address));
CREATE TABLE IF NOT EXISTS v2_indexer_checkpoints(network_key text PRIMARY KEY,slot bigint NOT NULL,observed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS v2_rooms(id uuid PRIMARY KEY,network_key text NOT NULL,match_address text NOT NULL,title text NOT NULL CHECK(char_length(title)<=60),host_address text NOT NULL,keeper_enabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(network_key,match_address));
CREATE TABLE IF NOT EXISTS v2_chat_messages(id bigserial PRIMARY KEY,room_id uuid NOT NULL REFERENCES v2_rooms(id) ON DELETE CASCADE,address text NOT NULL,body text NOT NULL CHECK(char_length(body)<=1000),created_at timestamptz NOT NULL DEFAULT now(),hidden_at timestamptz);
CREATE INDEX IF NOT EXISTS v2_chat_messages_room_cursor ON v2_chat_messages(room_id,id DESC);
CREATE TABLE IF NOT EXISTS v2_chat_mutes(room_id uuid NOT NULL REFERENCES v2_rooms(id) ON DELETE CASCADE,address text NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(room_id,address));
CREATE TABLE IF NOT EXISTS v2_ws_tickets(token_hash text PRIMARY KEY,session_hash text NOT NULL REFERENCES auth_sessions(token_hash) ON DELETE CASCADE,room_id uuid NOT NULL REFERENCES v2_rooms(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS v2_moderation_reports(id bigserial PRIMARY KEY,room_id uuid NOT NULL REFERENCES v2_rooms(id),message_id bigint REFERENCES v2_chat_messages(id),reporter text NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS v2_keeper_ledger(network_key text NOT NULL,intent_hash text NOT NULL,match_address text NOT NULL,stage smallint NOT NULL,phase smallint NOT NULL,revision bigint NOT NULL,actor text NOT NULL,state text NOT NULL CHECK(state IN('preparing','pending','confirmed','finalized','failed','expired','quarantined')),signature text,message_hash text,last_valid_block_height bigint,confirmed_slot bigint,fee_lamports bigint NOT NULL DEFAULT 0,spent_lamports bigint NOT NULL DEFAULT 0,attempts smallint NOT NULL DEFAULT 1,lease_token uuid,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(network_key,intent_hash));
CREATE INDEX IF NOT EXISTS v2_keeper_pending ON v2_keeper_ledger(network_key,state,updated_at);
